package com.zoutiw.bibla.data

object FirstThessaloniansData {
    val verses: List<Verse> = listOf(
        Verse(book = "1 Tesalonisyen", chapter = 1, verseNumber = 1, text = "Mwen menm, Pòl, ansanm ak Silven ak Timote, m'ap ekri lèt sa a voye bay manm legliz lavil Tesalonik yo, k'ap viv ansanm nan Bondye, Papa a, ak Jezikri, Seyè nou an. Mwen mande pou yo ban nou benediksyon ak kè poze.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 1, verseNumber = 2, text = "Se tout tan m'ap di Bondye mèsi pou nou tout. Mwen pa janm bliye nou lè m'ap lapriyè.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 1, verseNumber = 3, text = "Devan Bondye Papa nou, mwen toujou chonje jan n'ap viv byen paske nou gen konfyans nan Bondye, jan n'ap travay di paske nou gen renmen nan kè nou, jan nou rete fèm nan espwa nou gen nan Jezikri, Seyè nou an.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 1, verseNumber = 4, text = "Mwen konnen, frè m' yo, Bondye renmen nou, se li menm ki chwazi nou pou n' ka viv pou li.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 1, verseNumber = 5, text = "Se pa t' avèk pawòl ase mwen te anonse nou bon nouvèl la. Men tou, se te avèk pouvwa Sentespri a, avèk lasirans fèm sa m' t'ap di a se vre. Nou menm tou, nou konnen jan mwen te mennen tèt mwen nan mitan nou. Mwen te fè l' pou byen nou.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 1, verseNumber = 6, text = "Nou te swiv egzanp mwen ak egzanp Seyè a. Nou te soufri anpil. Malgre sa, nou te resevwa pawòl Bondye a ak kè kontan. Sa se travay Sentespri.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 1, verseNumber = 7, text = "Se konsa, nou te tounen yon egzanp pou tout moun nan peyi Masedwan ak nan peyi Lakayi ki gen konfyans nan Bondye.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 1, verseNumber = 8, text = "Konsa, nou fè anpil moun rive konnen mesaj Seyè a. Se pa sèlman nan Masedwan ak nan Lakayi, men se toupatou moun ap pale jan nou gen konfyans nan Bondye. Se sa ki fè, nou pa bezwen pale sou sa ankò.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 1, verseNumber = 9, text = "Okontrè, yo tout ap rakonte jan nou te resevwa m' lè m' te rive lakay nou, jan nou te kite zidòl yo pou n' tounen vin jwenn Bondye, pou nou te ka sèvi Bondye vivan an, Bondye tout bon an.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 1, verseNumber = 10, text = "Y'ap di tou jan n'ap tann Jezi, Pitit Bondye a, k'ap vini sot nan syèl la. Se Jezi sa a Bondye te leve vivan soti nan lanmò. Se li menm k'ap delivre nou anba kòlè Bondye k'ap vini an. 1 Tesalonik", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 2, verseNumber = 1, text = "Nou menm frè m' yo, nou konn sa byen: vizit mwen te fè lakay nou an te bay bon rezilta.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 2, verseNumber = 2, text = "Mwen te fenk soti lavil Filip kote yo te maltrete m' anpil, kote yo te joure m' lan. Men, Bondye ban m' fòs ak kouraj pou m' te ka anonse nou bon nouvèl ki soti nan li a, malgre tout opozisyon mwen te jwenn.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 2, verseNumber = 3, text = "Paske, lè m'ap pale ak moun, se pa manti m'ap bay, ni mwen pa gen ankenn move lide dèyè tèt mwen, ni mwen p'ap chache twonpe pesonn.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 2, verseNumber = 4, text = "Okontrè, mwen te toujou pale jan Bondye vle l' la. Se Bondye ki konnen sa ki nan kè mwen. Li fè m' konfyans, li ban mwen bon nouvèl li a pou m' anonse. Se sak fè, se pa lèzòm m'ap chache fè plezi, men Bondye ki konnen sa ki nan kè mwen.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 2, verseNumber = 5, text = "Nou menm, nou konn sa byen: mwen pa janm sèvi ak pawòl ki pou flate moun, ni mwen pa janm pran ankenn pretès pou chache fè lajan. Mwen pran Bondye pou temwen.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 2, verseNumber = 6, text = "Mwen pa chache lwanj nan men pesonn, ni nan men nou, ni nan men lòt moun.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 2, verseNumber = 7, text = "Se pa kapab mwen pa ta kapab fè nou santi otorite Kris la ban mwen tankou apòt li. Non, okontrè. Pandan tout tan m' te lakay nou, mwen te aji avèk dousè, tankou yon manman k'ap pran swen pitit li yo.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 2, verseNumber = 8, text = "Mwen te sitèlman renmen nou, se pa bon nouvèl la ase mwen ta ban nou. Ata vi m' mwen ta bay pou nou. Nou wè jan m' renmen nou!", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 2, verseNumber = 9, text = "Nou chonje, frè m' yo, jan m' te travay, jan m' te fatige kò m' ap travay lajounen kou lannwit pou m' pa t' sou kont nou yonn pandan tout tan mwen t'ap anonse nou bon nouvèl Bondye a.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 2, verseNumber = 10, text = "Mwen pran nou sèvi m' temwen ansanm ak Bondye: Nou menm ki gen konfyans nan Bondye, nou ka di mwen te aji byen ak nou, yon jan ki dakò ak volonte Bondye, yon jan ki dwat, ki san repwòch.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 2, verseNumber = 11, text = "Nou konnen ki jan mwen te aji ak nou chak, tankou yon papa ak pitit li yo.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 2, verseNumber = 12, text = "Mwen te ankouraje nou, mwen te konsole nou, mwen pa t' janm sispann fè nou konprann byen ki jan pou nou mennen tèt nou pou nou ka fè Bondye plezi, paske Bondye rele nou pou nou resevwa pa nou nan gouvènman l' ak nan bèl pouvwa li.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 2, verseNumber = 13, text = "Se konsa, mwen pa sispann di Bondye mèsi tou pou jan nou te pare zòrèy nou koute lè m' t'ap fè nou konnen pawòl Bondye a. Nou te resevwa l' pou sa l' ye a: pou pawòl Bondye, pa pou pawòl lèzòm. Se pawòl sa a k'ap travay nan kè nou, nou menm ki gen konfyans nan Bondye.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 2, verseNumber = 14, text = "Frè m' yo, sa ki rive nou an, se sa ki te rive manm legliz Bondye k'ap viv pou Jezikri nan peyi Jide a. Menm sa yo te soufri nan men jwif yo, se sa nou soufri tou nan men moun menm peyi ak nou yo.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 2, verseNumber = 15, text = "Se jwif yo ki te fè touye ni Jezi, Seyè a, ni pwofèt yo. Se yo menm tou ki te pèsekite m' ansanm ak zanmi m' yo. Yo pa soti pou fè Bondye plezi. Yo fè lènmi ak tout moun.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 2, verseNumber = 16, text = "Y'ap fè sa yo kapab pou anpeche m' pale ak moun ki pa jwif yo, pou moun sa yo pa sove. Konsa, yo lage kò yo nèt ale nan menm peche yo te toujou kònn fè a. Men, koulye a kòlè Bondye tonbe sou yo.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 2, verseNumber = 17, text = "Pou mwen menm, frè m' yo, pa gen lontan depi m' kite nou. Nou pa wè menm, se vre. Men, lide m' toujou sou nou. Se pa ti anvi mwen pa anvi wè nou ankò.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 2, verseNumber = 18, text = "Mwen pa konnen sa m' ta fè pou m' tounen lakay nou ankò. Mwen menm Pòl, mwen te seye plizyè fwa menm. Men, Satan te anpeche mwen.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 2, verseNumber = 19, text = "Se nou menm, moun Tesalonik, ki tout espwa mwen, se pa lòt moun. Se nou menm ki fè kè m' kontan. Se nou menm k'ap ban m' okazyon pou m' vante tèt mwen devan Jezi, Seyè nou an, lè la vini.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 2, verseNumber = 20, text = "Se nou menm ki ban m' satilfaksyon, se nou menm ki fè kè m' kontan. 1 Tesalonik", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 3, verseNumber = 1, text = "Se konsa, mwen pa t' kapab tann ankò. Mwen pran desizyon rete pou kont mwen lavil Atèn.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 3, verseNumber = 2, text = "Mwen te voye Timote, frè nou an, al wè nou. Se yon sèvitè Bondye k'ap travay ansanm ak mwen pou fè konnen bon nouvèl Kris la. Li te gen pou l' te fòtifye nou, pou l' te ankouraje nou nan lafwa,", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 3, verseNumber = 3, text = "pou pesonn pa febli nan mitan tribilasyon sa yo. Nou menm, moun lavil Tesalonik, se pou n' soufri bagay sa yo paske Bondye te wè davans sa tapral rive nou.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 3, verseNumber = 4, text = "Lè m' te la nan mitan nou, mwen te pale nou davans nou tapral gen anpil lafliksyon. Nou wè se sa menm ki rive nou.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 3, verseNumber = 5, text = "Se poutèt sa, mwen te voye Timote ban nou, mwen pa t' kapab tann ankò. Mwen te voye l' pran nouvèl jan konfyans nou nan Bondye ye. Mwen te pè pou Satan pa t' pran nou nan pèlen li, pou tout travay mwen an pa t' pèdi.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 3, verseNumber = 6, text = "Men koulye a, Timote fèk rive sot lakay nou, li fè kè m' kontan, li ban m' bon nouvèl, li di m' jan nou gen konfyans ak renmen. Li di m' jan nou menm tou nou toujou chonje m', jan nou anvi wè m', menm jan mwen menm mwen anvi wè nou.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 3, verseNumber = 7, text = "Konsa, frè m' yo, nan mitan tout fikilte ak tout lafliksyon mwen yo, sa te ban m' kouraj lè m' tande jan n'ap kenbe fèm nan lafwa.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 3, verseNumber = 8, text = "Se koulye a m'ap viv tout bon, paske nou menm, moun Tesalonik, nou rete fèm nan lavi n'ap mennen ansanm ak Kris la.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 3, verseNumber = 9, text = "Mwen pa konn ki jan pou m' di Bondye mèsi pou nou, tèlman nou fè kè m' kontan devan li.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 3, verseNumber = 10, text = "Lajounen kou lannwit, m'ap mande ak tout kè mwen pou Bondye ban m' chans yon lè vizite nou ankò, pou m' ka fin moutre nou sa nou manke nan lafwa a toujou.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 3, verseNumber = 11, text = "Mwen mande Bondye, Papa nou, ansanm ak Jezikri, Seyè nou, pou yo louvri yon chemen pou mwen pou m' ka vin wè nou.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 3, verseNumber = 12, text = "Mwen mande Seyè a pou nou gen plis renmen yonn pou lòt ak pou tout moun, menm jan mwen renmen nou.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 3, verseNumber = 13, text = "Konsa, nou menm moun Tesalonik, Kris la va fòtifye kè nou pou nou ka san repwòch devan Bondye, Papa nou, tankou moun k'ap viv apa pou li jouk lè Jezikri, Seyè nou an, va vini ansanm ak tout moun pa l' yo. 1 Tesalonik", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 4, verseNumber = 1, text = "Frè m' yo, mwen te moutre nou ki jan pou n' mennen bak nou si nou vle fè Bondye plezi. Wi, mwen konnen se konsa n'ap viv vre. Men, koulye a m'ap mande nou, nan non Seyè Jezi a, tanpri chache viv pi byen toujou.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 4, verseNumber = 2, text = "Nou konnen tou sa m' te moutre nou, avèk otorite Seyè Jezi te ban mwen an.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 4, verseNumber = 3, text = "Men sa Bondye vle pou nou: Se pou nou viv apa pou Bondye, pou nou pa lage kò nou nan imoralite.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 4, verseNumber = 4, text = "Se pou chak gason konn chwazi madanm li yon jan ki respektab, ki dakò ak volonte Bondye.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 4, verseNumber = 5, text = "Pa kite move lanvi pouse nou tankou moun lòt nasyon yo ki pa konnen Bondye.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 4, verseNumber = 6, text = "Nan bagay sa a, ankenn gason pa dwe fè frè l' lapenn, ni fè l' lenjistis. Mwen deja di nou sa, mwen te ban nou kont avètisman sou sa: Seyè a gen pou peni moun ki fè bagay konsa.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 4, verseNumber = 7, text = "Bondye pa rele nou pou nou viv nan vye kondisyon lèd. Men, li rele nou pou nou viv yon jan ki dakò ak volonte li.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 4, verseNumber = 8, text = "Se poutèt sa, moun ki pa asepte pawòl sa a, se pa pawòl lèzòm li pa koute, se pawòl Bondye ki ban nou Sentespri l' la menm li pa koute.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 4, verseNumber = 9, text = "Kanta renmen nou dwe genyen pou frè n' yo, mwen pa bezwen ekri nou sou sa. Paske, se Bondye menm ki te moutre nou ki jan nou dwe yonn renmen lòt.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 4, verseNumber = 10, text = "Mwen konnen se konsa menm n'ap aji avèk tout frè yo nan tout peyi Masedwan lan. Men, m'ap mande nou, frè m' yo, pou nou chache viv pi byen toujou.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 4, verseNumber = 11, text = "Chache viv ak kè poze. Okipe zafè pa nou. Travay ak men nou pou nou pa rete sou kont moun.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 4, verseNumber = 12, text = "Konsa, moun ki pa kwè nan Kris la va respekte nou, epi nou menm, nou p'ap rete sou kont pesonn.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 4, verseNumber = 13, text = "Frè m' yo, sou keksyon moun ki mouri deja yo, mwen ta renmen nou konn verite a, pou nou pa gen lapenn tankou lòt moun yo ki pa gen espwa nan Seyè a.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 4, verseNumber = 14, text = "Menm jan nou kwè Jezi te mouri epi li te leve soti vivan ankò a, konsa tou, se pou n' kwè tout moun ki te gen konfyans nan li lè yo te mouri, Bondye va fè yo tounen ansanm ak Jezi.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 4, verseNumber = 15, text = "Dapre sa Seyè a te moutre m' lan, men sa m'ap di nou: Nou menm k'ap vivan toujou lè Seyè a va vini an, nou p'ap pran devan moun ki mouri deja yo.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 4, verseNumber = 16, text = "Lè sa a, n'a tande yon gwo lòd pase, n'a tande vwa chèf zanj lan ansanm ak kout klewon Bondye a: epi Seyè a menm va desann sot nan syèl la. Moun ki te mete konfyans yo nan Kris la lè yo te mouri, se yo ki va leve soti vivan an premye.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 4, verseNumber = 17, text = "Apre sa, nou menm ki va vivan toujou lè sa a, y'ap vin pran nou, nou menm ansanm ak moun ki soti vivan nan lanmò yo, y'ap mete nou sou nwaj yo pou n' al kontre Seyè a anwo a. Konsa, nou tout n'ap toujou ansanm ak Seyè a.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 4, verseNumber = 18, text = "Se pou nou yonn ankouraje lòt ak pawòl sa yo. 1 Tesalonik", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 5, verseNumber = 1, text = "Frè m' yo, mwen pa bezwen ekri nou pou m' fè nou konnen ni ki lè, ni ki jou bagay sa yo gen pou rive.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 5, verseNumber = 2, text = "Nou menm nou konn sa byen: Jou Seyè a gen pou l' vin sou nou tankou yon vòlò k'ap vin nan mitan lannwit.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 5, verseNumber = 3, text = "Lè n'ap tande moun ap di: Gen lapè toupatou, tout bagay byen sou kontwòl, se lè sa a, san nou pa atann, n'ap wè kòlè Bondye a tonbe sou yo pou detwi yo. Se tankou lè doulè tranche sezi yon fanm ansent. p'ap gen chape pou yo.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 5, verseNumber = 4, text = "Men nou menm, frè m' yo, nou pa moun k'ap viv nan fènwa. Jou sa a p'ap vin sou nou tankou yon vòlè, san nou pa atann.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 5, verseNumber = 5, text = "Paske, nou tout se moun k'ap viv nan limyè, nan gwo lajounen. Nou pa moun k'ap viv nan lannwit, nan fènwa!", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 5, verseNumber = 6, text = "Se sak fè, piga nou dòmi tankou lòt yo. Pa kite dòmi pran nou. Kenbe tèt nou anplas.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 5, verseNumber = 7, text = "Se lannwit moun dòmi. Se lannwit tou moun sou.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 5, verseNumber = 8, text = "Men nou menm, nou se moun k'ap viv lajounen, se pou nou toujou kenbe tèt nou anplas. Ann pran konfyans nou gen nan Bondye a ak renmen nou gen nan kè nou tankou yon plak pwotèj pou lestonmak nou. Ann pran espwa nou genyen nan Jezi k'ap vin delivre nou nèt la, ann mete l' tankou yon kas an fè nan tèt nou.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 5, verseNumber = 9, text = "Paske, Bondye pa t' chwazi nou pou nou te tonbe anba kòlè li, men pou n' te ka delivre, gremesi Jezikri, Seyè nou an.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 5, verseNumber = 10, text = "Jezi te mouri pou n' te ka viv ansanm ak li. Konsa, kit nou mouri deja, kit nou vivan toujou lè la vini an, nou tout n'ap toujou ansanm ak li.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 5, verseNumber = 11, text = "Se poutèt sa, annou yonn ankouraje lòt, yonn ede lòt, jan nou deja ap fè l' la.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 5, verseNumber = 12, text = "Frè m' yo, m'ap mande nou pou nou gen anpil respè pou moun k'ap travay nan mitan nou yo, moun Seyè a chwazi pou dirije nou, pou ankouraje nou.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 5, verseNumber = 13, text = "Se pou nou gen anpil konsiderasyon pou yo, se pou nou renmen yo poutèt travay y'ap fè a. Se pou nou viv byen ak kè poze yonn ak lòt.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 5, verseNumber = 14, text = "M'ap mande nou tou, frè m' yo, pou nou rele dèyè moun k'ap fè parese yo. Ankouraje sa ki yon ti jan frèt yo, ede sa ki fèb yo. Se pou nou pran pasyans ak tout moun.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 5, verseNumber = 15, text = "Pa kite pesonn rann mal pou mal. Okontrè, toujou chache fè sa ki byen yonn pou lòt ak sa ki byen pou tout moun.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 5, verseNumber = 16, text = "Se pou kè nou toujou kontan.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 5, verseNumber = 17, text = "Pa janm sispann lapriyè.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 5, verseNumber = 18, text = "Di Bondye mèsi pou tout bagay. Se sa Bondye mande nou, nou menm ki mete konfyans nou nan Jezikri.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 5, verseNumber = 19, text = "Pa antrave travay Sentespri a.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 5, verseNumber = 20, text = "Pa meprize pawòl moun k'ap bay mesaj ki soti nan Bondye.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 5, verseNumber = 21, text = "Egzaminen tout bagay byen, kenbe sa ki bon.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 5, verseNumber = 22, text = "Egzante tou sa ki mal.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 5, verseNumber = 23, text = "Mwen mande Bondye ki bay kè poze a pou l' fè nou favè pou nou viv pou li nèt ale. Konsa, lè Jezikri, Seyè nou an, va vini, li p'ap jwenn nou ak ankenn defo, ni nan kò nou, ni nan lespri nou ni nan nanm nou.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 5, verseNumber = 24, text = "Bondye ki rele nou an va fè sa pou nou, paske li toujou kenbe pawòl li.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 5, verseNumber = 25, text = "Frè m' yo, lapriyè pou mwen tou.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 5, verseNumber = 26, text = "Di tout frè yo bonjou, bo yo pou mwen tankou moun k'ap viv pou Bondye konn fè l' la.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 5, verseNumber = 27, text = "Tanpri souple, nan non Seyè a, li lèt sa a bay tout frè yo.", bookId = 52),
        Verse(book = "1 Tesalonisyen", chapter = 5, verseNumber = 28, text = "Se pou benediksyon Jezikri, Seyè nou an, toujou la avèk nou. 1 Tesalonik", bookId = 52)
    )
}

